/**
 * The Pixcue name on an LED matrix, as plain data: the wordmark in the top
 * bar and the brand images (favicon, app icons, social preview, generated by
 * scripts/brand-assets.ts) draw the same cells.
 */

/** 5×7 letters (I is 3 wide), one clear column apart. */
const LETTERS: readonly (readonly string[])[] = [
  ['####.', '#...#', '#...#', '####.', '#....', '#....', '#....'],
  ['###', '.#.', '.#.', '.#.', '.#.', '.#.', '###'],
  ['#...#', '#...#', '.#.#.', '..#..', '.#.#.', '#...#', '#...#'],
  ['.####', '#....', '#....', '#....', '#....', '#....', '.####'],
  ['#...#', '#...#', '#...#', '#...#', '#...#', '#...#', '.###.'],
  ['#####', '#....', '#....', '####.', '#....', '#....', '#####'],
];

export interface Cell {
  readonly x: number;
  readonly y: number;
  readonly lit: boolean;
}

export interface Matrix {
  readonly cells: readonly Cell[];
  readonly cols: number;
  readonly rows: number;
}

/** Lays out letters on a grid with `pad` unlit cells around them. */
function matrix(letters: readonly (readonly string[])[], pad: number, minCols = 0): Matrix {
  const lit = new Set<string>();
  const width = letters.reduce((w, l) => w + (l[0]?.length ?? 0), 0) + letters.length - 1;
  const cols = Math.max(width + pad * 2, minCols);
  let x = Math.floor((cols - width) / 2);
  for (const letter of letters) {
    letter.forEach((row, y) => {
      [...row].forEach((c, dx) => {
        if (c === '#') lit.add(`${x + dx},${y + pad}`);
      });
    });
    x += (letter[0]?.length ?? 0) + 1;
  }
  const rows = 7 + pad * 2;
  const cells: Cell[] = [];
  for (let cy = 0; cy < rows; cy++) {
    for (let cx = 0; cx < cols; cx++) cells.push({ x: cx, y: cy, lit: lit.has(`${cx},${cy}`) });
  }
  return { cells, cols, rows };
}

/** PIXCUE with one unlit cell around it. */
export const WORDMARK = matrix(LETTERS, 1);

/** The P alone on a square 9×9 matrix: the icon. */
export const MONOGRAM = matrix(LETTERS.slice(0, 1), 1, 9);

/** The brand's colors (from the studio's tokens). */
export const BRAND = {
  ground: '#000000',
  ink: '#ff2a2a',
  unlit: '#1a1a1a',
  text: '#ededed',
} as const;
